function login(forgot,step){
 R.innerHTML='<section class="auth-page"><div class="auth-brand"><span class="tl-brand-mark">T</span><span><strong style="font:800 15px Manrope;color:#172b43;display:block">TEMPEST LEADS</strong><small style="font-size:9px;color:#6d7e8d;letter-spacing:1px">ACQUISITION CRM</small></span></div><div class="auth-card">'+(forgot?forgotHtml(step||0):loginHtml())+'</div><aside class="auth-art"><div><p class="eyebrow">TEMPEST ADVERTISING</p><h2>Turn every opportunity into <b>a clear next move.</b></h2><p>A disciplined workspace for acquisition, onboarding and long-term nurture.</p></div></aside></section>';
}
function loginHtml(){return '<p class="eyebrow">SECURE WORKSPACE</p><h1>Welcome back</h1><p>Sign in to TEMPEST LEADS.</p><form data-form="login"><label>Email<input name="email" type="email" placeholder="name@tempest.demo" required></label><label>Password<span class="password-field"><input name="password" id="password" type="password" placeholder="Enter your password" required><button type="button" data-action="show-pass">Show</button></span></label><div class="auth-row"><label><input type="checkbox" checked> Remember me</label><a href="#" data-action="forgot">Forgot password?</a></div><button class="tl-primary" style="width:100%" type="submit">Log in</button></form><div class="demo-roles"><p>Demo workspace</p>'+button('Open as Super Admin','demo-admin')+button('Open as Owner','demo-owner')+'</div>'}
function forgotHtml(s){if(s===0)return '<p class="eyebrow">PASSWORD RESET</p><h1>Reset your password</h1><p>Enter your registered email or username. The verification step is simulated in this MVP.</p><form data-form="forgot"><label>Registered email<input name="email" type="email" required></label><div class="auth-row"><a href="#" data-action="back-login">Back to login</a></div><button class="tl-primary" style="width:100%" type="submit">Continue</button></form>';if(s===1)return '<p class="eyebrow">VERIFICATION</p><h1>Check your inbox</h1><p>In production, a one-time reset link would be sent. Confirm verification to continue in this demo.</p>'+button('Verify and continue','verify-reset','tl-primary')+'<div class="auth-row"><a href="#" data-action="back-login">Back to login</a></div>';if(s===2)return '<p class="eyebrow">NEW PASSWORD</p><h1>Choose a new password</h1><p>Use at least eight characters.</p><form data-form="reset"><label>New password<input name="password" type="password" minlength="8" required></label><label>Confirm password<input name="confirm" type="password" minlength="8" required></label><button class="tl-primary" style="width:100%" type="submit">Reset password</button></form>';return '<p class="eyebrow">PASSWORD RESET</p><h1>Password updated</h1><p>Your password was reset in this simulated flow. Return to login to continue.</p>'+button('Return to login','back-login','tl-primary')}
function auth(id){session={id};sessionStorage.setItem(S,JSON.stringify(session));U.route='dashboard';location.hash='dashboard';render()}
const nav=[['WORKSPACE','dashboard','▦','Dashboard'],['','leads','◫','Leads & Pipeline'],['','companies','▣','Companies'],['','contacts','♙','Contacts'],['','activities','◷','Activities'],['','meetings','◴','Meetings'],['','followups','✓','Follow-ups'],['LIFECYCLE','nurture','↻','Nurture'],['','pitch','◐','Pitch'],['','commercials','₹','Commercials'],['','contracts','▤','Contracts / PO'],['','onboarding','□','Onboarding'],['','clients','★','Active Clients'],['','reports','◌','Reports / Analytics']];
const navAdmin=[['ADMINISTRATION','users','♟','Users / Owners'],['','team','⌁','Team Performance'],['','settings','⚙','Settings'],['','audit','◉','Audit Log']];
const adminRoutes=['users','team','settings','audit'];
function navHtml(xs){return xs.map(z=>(z[0]?'<div class="nav-section">'+z[0]+'</div>':'')+'<button class="tl-nav '+(U.route===z[1]?'active':'')+'" data-go="'+z[1]+'" title="'+z[3]+'"><span class="nav-icon">'+z[2]+'</span><span class="nav-label">'+z[3]+'</span></button>').join('')}
function render(){
 if(!session||!user()){login();return}if(adminRoutes.includes(U.route)&&!admin()){deny();return}
 let u=user(), unread=D.notifications.filter(n=>n.unread).length;
 R.innerHTML='<div class="tl-shell"><aside class="tl-sidebar" id="side"><div class="tl-brand"><span class="tl-brand-mark">T</span><span class="brand-copy"><strong>TEMPEST LEADS</strong><small>ACQUISITION CRM</small></span></div><nav>'+navHtml(nav)+(admin()?navHtml(navAdmin):'')+'</nav><div class="tl-profile"><span class="tl-avatar">'+initials(u.name)+'</span><span class="profile-copy"><b>'+x(u.name)+'</b><small>'+x(u.location)+'</small></span><span class="role-chip">'+(admin()?'ADMIN':'OWNER')+'</span></div></aside><section class="tl-main"><header class="tl-topbar">'+button('☰','menu','icon-control')+'<div class="top-search"><span>⌕</span><input id="global" value="'+x(U.query)+'" placeholder="Search company, contact, lead or owner…"><kbd>⌘ K</kbd></div><span class="top-spacer"></span><span class="top-followup">'+mine().filter(l=>l.follow===DAY&&l.status==='Open').length+' due today</span><div class="notification-wrap">'+button('♧','notifications','icon-control')+'<i class="'+(unread?'unread':'')+'"></i><div id="notes"></div></div><button class="tl-avatar" data-action="profile">'+initials(u.name)+'</button></header><main class="tl-page" id="page"></main></section></div>';
 route();
}
function initials(n){return n.split(' ').map(z=>z[0]).join('').slice(0,2)}
function deny(){R.innerHTML='<section class="auth-page"><div class="auth-card access-denied"><p class="eyebrow">ACCESS CONTROL</p><h1>Access denied</h1><p>Your Owner role cannot access this admin-only area. Return to your dashboard to view records assigned to you.</p>'+button('Return to dashboard','return-dashboard','tl-primary')+'</div><aside class="auth-art"><div><h2>Role-based <b>record access.</b></h2></div></aside></section>'}
function go(r){U.route=r;location.hash=r;render()}
function route(){let f={dashboard:dashboard,leads:leads,companies:companies,contacts:contacts,activities:activities,meetings:meetings,followups:followups,nurture:nurture,pitch:module,commercials:module,contracts:module,onboarding:module,clients:clients,reports:reports,users:users,team:team,settings:settings,audit:auditPage,search:search};(f[U.route]||dashboard)()}
function dashboard(){
 let p=document.querySelector('#page'),ls=mine(),open=ls.filter(l=>!['Lost','Nurture','Active Client'].includes(l.stage)),over=ls.filter(l=>sooner(l.follow)&&l.status==='Open'),f=D.followups.filter(q=>can(lead(q.lead))&&['Due today','Overdue'].includes(q.status));
 const cards=[['Total leads',ls.length,'All records','leads'],['New leads',ls.filter(l=>l.stage==='New').length,'This week','leads'],['Active pipeline',open.length,'₹'+Math.round(open.reduce((a,l)=>a+l.value,0)/100000)+'L opportunity','leads'],['Meetings scheduled',D.meetings.filter(m=>can(lead(m.lead))&&m.status==='Scheduled').length,'Upcoming','meetings'],['Pitches in progress',ls.filter(l=>l.stage==='Pitch').length,'Needs review','pitch'],['Commercials pending',ls.filter(l=>l.stage==='Commercials').length,'Negotiation','commercials'],['Contracts pending',ls.filter(l=>l.stage==='Contract / PO').length,'PO or signature','contracts'],['Onboarding pending',ls.filter(l=>l.stage==='Onboarding').length,'Mandatory gates','onboarding'],['Active clients',ls.filter(l=>l.stage==='Active Client').length,'Converted','clients'],['Lost leads',ls.filter(l=>l.stage==='Lost').length,'Preserved history','nurture'],['Nurture leads',ls.filter(l=>l.stage==='Nurture').length,'Reconnect planned','nurture'],['Overdue follow-ups',over.length,over.length?'Immediate action required':'No missed actions','followups']];
 p.innerHTML=title(admin()?'Super Admin Dashboard':'My Dashboard',admin()?'A complete view of acquisition performance, critical actions and ownership.':'Your execution dashboard. Start with today’s next actions.',button('Export','export-dashboard')+button('+ Add Lead','add-lead','tl-primary'))+'<section class="kpi-grid">'+cards.map(c=>'<button class="tl-kpi" data-go="'+c[3]+'"><span>'+c[0]+'</span><b>'+c[1]+'</b><small>'+c[2]+'</small></button>').join('')+'</section><section class="tl-grid"><article class="tl-card"><div class="tl-card-head"><h2>PIPELINE OVERVIEW</h2>'+button('Open pipeline →','open-leads','tl-link')+'</div>'+STAGES.map((s,i)=>pipeRow(s,ls.filter(l=>l.stage===s),ls.length,i)).join('')+'</article><aside><article class="tl-card urgent-panel"><div class="tl-card-head"><h2>'+ (admin()?'MISSED / OVERDUE':'TODAY’S ACTIONS')+'</h2>'+button('View all →','open-followups','tl-link')+'</div>'+f.slice(0,5).map(q=>urgent(q)).join('')+(f.length?'':'<p class="muted">No urgent follow-ups.</p>')+'</article><article class="tl-card" style="margin-top:17px"><div class="tl-card-head"><h2>'+ (admin()?'OWNER PERFORMANCE':'MY PIPELINE')+'</h2>'+button('Open →',admin()?'open-team':'open-leads','tl-link')+'</div>'+ (admin()?ownerList():mine().filter(l=>!['Lost','Nurture'].includes(l.stage)).map(l=>'<div class="urgent-item"><b>'+x(co(l.company).name)+'</b><span class="top-spacer"></span>'+stage(l.stage)+'</div>').join(''))+'</article></aside></section>'+ (admin()?'<section class="tl-grid"><article class="tl-card"><div class="tl-card-head"><h2>SOURCE PERFORMANCE</h2></div>'+breakdown(ls,'source')+'</article><article class="tl-card"><div class="tl-card-head"><h2>INDUSTRY PERFORMANCE</h2></div>'+breakdown(ls,'industry')+'</article></section>':'');
}
function pipeRow(s,rows,total,i){let v=rows.reduce((a,l)=>a+l.value,0);return '<div class="pipeline-row2"><span>'+s+'</span><div class="progress"><i style="width:'+Math.max(3,rows.length/Math.max(total,1)*100)+'%;background:'+['#2582ae','#3476bd','#438aca','#7c68c4','#9a62bd','#c47734','#b85c62','#be4d62','#4e9f83','#198a67'][i]+'"></i></div><b>'+rows.length+'</b><small>₹'+Math.round(v/100000)+'L</small></div>'}
function urgent(q){let l=lead(q.lead);return '<div class="urgent-item"><span class="priority '+q.priority.toLowerCase()+'">'+(q.status==='Overdue'?'OVERDUE':q.time)+'</span><div class="urgent-copy"><b>'+x(co(l.company).name)+' · '+x(q.action)+'</b><small>'+x(ct(l.contact).name)+' · '+x(ow(l.owner).name)+' · '+l.stage+'</small></div>'+button('Complete','complete-'+q.id,'tl-link')+'</div>'}
function ownerList(){return D.users.filter(u=>u.status==='Active').map(u=>{let ls=D.leads.filter(l=>l.owner===u.id),o=ls.filter(l=>sooner(l.follow)&&l.status==='Open').length;return '<div class="urgent-item"><span class="tl-avatar">'+initials(u.name)+'</span><div class="urgent-copy"><b>'+x(u.name)+'</b><small>'+ls.length+' leads · '+ls.filter(l=>l.stage==='Active Client').length+' clients · '+o+' overdue</small></div><b>'+ls.filter(l=>!['Lost','Nurture','Active Client'].includes(l.stage)).length+' active</b></div>'}).join('')}
function breakdown(ls,k){let o={};ls.forEach(l=>{let n=k==='industry'?co(l.company).industry:l.source;o[n]=(o[n]||0)+1});return Object.entries(o).sort((a,b)=>b[1]-a[1]).slice(0,6).map(q=>'<div class="pipeline-row2"><span>'+x(q[0])+'</span><div class="progress"><i style="width:'+q[1]/ls.length*100+'%"></i></div><b>'+q[1]+'</b><small>'+Math.round(q[1]/ls.length*100)+'%</small></div>').join('')}
function leads(){
 let p=document.querySelector('#page'),ls=mine().filter(l=>(!U.query||[l.id,co(l.company).name,ct(l.contact).name,ct(l.contact).email,ct(l.contact).phone].join(' ').toLowerCase().includes(U.query.toLowerCase()))&&(!U.filter||l.stage===U.filter));
 p.innerHTML=title('Leads & Pipeline','Every open lead has an owner, stage, last touch and next action.',button(U.kanban?'Table view':'Kanban view','toggle-kanban')+button('Export','export-leads')+button('+ Add Lead','add-lead','tl-primary'))+'<div class="tl-filters"><input class="filter-input" id="leadQuery" value="'+x(U.query)+'" placeholder="Search ID, company, contact, email or phone"><select class="filter-select" id="leadStage"><option value="">All stages</option>'+STAGES.concat(['Lost','Nurture']).map(s=>'<option '+(U.filter===s?'selected':'')+'>'+s+'</option>').join('')+'</select>'+button('Assign owner','bulk-owner')+button('Change stage','bulk-stage')+'</div>'+(U.kanban?kanban(ls):leadTable(ls));
}
function leadTable(ls){return '<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th><input id="all" type="checkbox"></th><th>Lead ID</th><th>Company / contact</th><th>Industry</th><th>Source</th><th>Owner</th><th>Stage</th><th>Priority</th><th>Last touch</th><th>Next action</th><th>Follow-up</th></tr></thead><tbody>'+ls.map(l=>'<tr data-lead="'+l.id+'"><td><input class="pick" value="'+l.id+'" type="checkbox"></td><td><b>'+l.id+'</b><small>'+l.status+'</small></td><td><b>'+x(co(l.company).name)+'</b><small>'+x(ct(l.contact).name)+'</small></td><td>'+x(co(l.company).industry)+'</td><td>'+x(l.source)+'</td><td>'+x(ow(l.owner).name)+'</td><td>'+stage(l.stage)+'</td><td>'+pri(l.priority)+'</td><td>'+date(l.last)+'</td><td>'+x(l.next)+'</td><td>'+date(l.follow)+'<small>'+l.time+'</small></td></tr>').join('')+(ls.length?'':empty('No leads found','Clear filters or add a new company lead.'))+'</tbody></table></div><div class="table-pagination"><span>'+ls.length+' records</span><span>Page 1 of 1</span></div></article>'}
function kanban(ls){return '<article class="kanban">'+STAGES.concat(['Lost','Nurture']).map(s=>'<section class="kanban-col" data-drop="'+s+'"><header><span>'+s+'</span><b>'+ls.filter(l=>l.stage===s).length+'</b></header>'+ls.filter(l=>l.stage===s).map(l=>'<article class="kanban-card" data-lead="'+l.id+'" draggable="true"><b>'+x(co(l.company).name)+'</b><small>'+x(ct(l.contact).name)+' · '+x(ow(l.owner).name)+'</small><footer>'+pri(l.priority)+'<small>'+date(l.follow)+' · '+l.age+'d</small></footer></article>').join('')+'</section>').join('')+'</article>'}
function companies(){let p=document.querySelector('#page'),cs=admin()?D.companies:D.companies.filter(c=>mine().some(l=>l.company===c.id));p.innerHTML=title('Company Master','One company record supports multiple contacts, leads and interactions.',button('Export','export-companies')+button('+ Add company','add-company','tl-primary'))+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Company ID</th><th>Company / brand</th><th>Industry</th><th>City</th><th>Website</th><th>Existing agency</th><th>Source</th><th>Status</th><th>Contacts</th></tr></thead><tbody>'+cs.map(c=>'<tr data-company="'+c.id+'"><td>'+c.id+'</td><td><b>'+x(c.name)+'</b></td><td>'+x(c.industry)+'</td><td>'+x(c.city)+'</td><td>'+x(c.website)+'</td><td>'+x(c.agency)+'</td><td>'+x(c.source)+'</td><td>'+stage(c.status)+'</td><td>'+D.contacts.filter(q=>q.company===c.id).length+'</td></tr>').join('')+'</tbody></table></div></article>'}
function contacts(){let p=document.querySelector('#page'),cs=admin()?D.contacts:D.contacts.filter(c=>mine().some(l=>l.company===c.company));p.innerHTML=title('Contact Master','Contacts are independent records. A company can have many decision-makers and stakeholders.',button('Export','export-contacts')+button('+ Add contact','add-contact','tl-primary'))+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Contact ID</th><th>Name</th><th>Company</th><th>Designation</th><th>Phone</th><th>Email</th><th>Decision maker</th></tr></thead><tbody>'+cs.map(c=>'<tr><td>'+c.id+'</td><td><b>'+x(c.name)+'</b></td><td>'+x(co(c.company).name)+'</td><td>'+x(c.designation)+'</td><td>'+x(c.phone)+'</td><td>'+x(c.email)+'</td><td>'+ (c.decision?'Yes':'No')+'</td></tr>').join('')+'</tbody></table></div></article>'}
function activities(){let p=document.querySelector('#page'),as=D.activities.filter(a=>can(lead(a.lead)));p.innerHTML=title('Activity Log','A chronological record of every material interaction and workflow change.',button('+ Add activity','add-activity','tl-primary'))+'<article class="tl-card"><div class="timeline">'+as.map(a=>'<div class="timeline-item"><b>'+x(a.type)+' · '+x(co(lead(a.lead).company).name)+' · '+x(a.outcome)+'</b><small>'+date(a.date)+' · '+x(ow(a.owner).name)+'</small><small>'+x(a.notes)+'</small></div>').join('')+'</div></article>'}
function meetings(){let p=document.querySelector('#page'),ms=D.meetings.filter(m=>can(lead(m.lead)));p.innerHTML=title('Meetings','Schedule, complete and preserve every discovery or client conversation.',button('+ Schedule meeting','add-meeting','tl-primary'))+recordTable(ms,['company','title','date','time','type','status'],'meeting')}
function followups(){let p=document.querySelector('#page'),fs=D.followups.filter(f=>can(lead(f.lead))).sort((a,b)=>a.date.localeCompare(b.date));p.innerHTML=title('Follow-ups','Open records stay visible until you capture the outcome and the next move.',button('+ Schedule follow-up','add-followup','tl-primary'))+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Company</th><th>Contact</th><th>Owner</th><th>Stage</th><th>Due</th><th>Action</th><th>Priority</th><th>Last touch</th><th></th></tr></thead><tbody>'+fs.map(f=>{let l=lead(f.lead);return '<tr><td><b>'+x(co(l.company).name)+'</b></td><td>'+x(ct(l.contact).name)+'</td><td>'+x(ow(l.owner).name)+'</td><td>'+stage(l.stage)+'</td><td>'+date(f.date)+'<small>'+f.time+'</small></td><td>'+x(f.action)+'</td><td>'+pri(f.priority)+'</td><td>'+date(l.last)+'</td><td>'+button('Complete','complete-'+f.id,'tl-link')+'</td></tr>'}).join('')+'</tbody></table></div></article>'}
function nurture(){let p=document.querySelector('#page'),ls=mine().filter(l=>['Nurture','Lost'].includes(l.stage));p.innerHTML=title('Nurture Database','Keep “later”, no-response and lost opportunities segmentable and ready to reconnect.',button('+ Schedule reconnect','add-reconnect','tl-primary'))+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Company</th><th>Contact</th><th>Category</th><th>Reason</th><th>Industry</th><th>Owner</th><th>Last touch</th><th>Reconnect</th></tr></thead><tbody>'+ls.map(l=>'<tr data-lead="'+l.id+'"><td><b>'+x(co(l.company).name)+'</b></td><td>'+x(ct(l.contact).name)+'</td><td>'+stage(l.stage==='Lost'?'Lost / Not Interested':l.status)+'</td><td>'+x(l.reason||'—')+'</td><td>'+x(co(l.company).industry)+'</td><td>'+x(ow(l.owner).name)+'</td><td>'+date(l.last)+'</td><td>'+date(l.follow)+'</td></tr>').join('')+'</tbody></table></div></article>'}
function recordTable(rows,keys,kind){return '<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr>'+keys.map(k=>'<th>'+k+'</th>').join('')+'<th></th></tr></thead><tbody>'+rows.map(r=>{let l=lead(r.lead);return '<tr data-'+kind+'="'+r.id+'">'+keys.map(k=>'<td>'+ (k==='company'?'<b>'+x(co(l.company).name)+'</b>':k==='status'?stage(r[k]):x(r[k]||'—'))+'</td>').join('')+'<td>'+button(r.status==='Scheduled'?'Complete':'Open','complete-meeting-'+r.id,'tl-link')+'</td></tr>'}).join('')+'</tbody></table></div></article>'}
function module(){let meta={pitch:['Pitch Management','Versioned pitch records, assigned teams and review gates.'],commercials:['Commercials','Versioned quotations preserve negotiation history.'],contracts:['Contracts / PO','Track scope, price, payment terms and approval status.'],onboarding:['Onboarding','A formal gate before an opportunity becomes an active client.']}[U.route];let ls=mine().filter(l=>({pitch:'Pitch',commercials:'Commercials',contracts:'Contract / PO',onboarding:'Onboarding'}[U.route]===l.stage));document.querySelector('#page').innerHTML=title(meta[0],meta[1],button('+ Add record','module-record','tl-primary'))+(ls.length?leadTable(ls):empty('No '+meta[0].toLowerCase()+' records','Open a lead’s lifecycle tab to create a contextual record.'))}
function clients(){let p=document.querySelector('#page');p.innerHTML=title('Active Clients','Converted client profiles retain the relationship, commercial and delivery context.',button('Export','export-clients'))+leadTable(mine().filter(l=>l.stage==='Active Client'))}
function reports(){let p=document.querySelector('#page'),ls=mine();p.innerHTML=title('Reports & Analytics','Objective metrics for acquisition, conversion, follow-up discipline and stage aging.',button('Export report','export-reports'))+'<section class="tl-grid"><article class="tl-card"><div class="tl-card-head"><h2>STAGE DISTRIBUTION</h2></div>'+STAGES.map((s,i)=>pipeRow(s,ls.filter(l=>l.stage===s),ls.length,i)).join('')+'</article><article class="tl-card"><div class="tl-card-head"><h2>CONVERSION & FOLLOW-UP</h2></div><div class="info-grid"><div class="info-field"><small>Active client conversion</small><b>'+Math.round(ls.filter(l=>l.stage==='Active Client').length/ls.length*100)+'%</b></div><div class="info-field"><small>Open pipeline</small><b>'+ls.filter(l=>l.status==='Open').length+'</b></div><div class="info-field"><small>Overdue follow-ups</small><b>'+ls.filter(l=>sooner(l.follow)&&l.status==='Open').length+'</b></div><div class="info-field"><small>Average stage aging</small><b>'+Math.round(ls.reduce((a,l)=>a+l.age,0)/ls.length)+' days</b></div></div><div class="tl-card-head" style="margin-top:24px"><h2>LEADS BY SOURCE</h2></div>'+breakdown(ls,'source')+'</article></section>'}
function users(){let p=document.querySelector('#page');p.innerHTML=title('Users / Owners','Manage active owners. Deactivation reassigns owned leads to Super Admin by default.',button('+ Add user','add-user','tl-primary'))+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Department</th><th>Location</th><th>Status</th><th>Assigned leads</th><th>Last login</th><th></th></tr></thead><tbody>'+D.users.map(u=>'<tr><td><b>'+x(u.name)+'</b></td><td>'+x(u.email)+'</td><td>'+stage(u.role==='SUPER ADMIN'?'Admin':'Owner')+'</td><td>'+x(u.department)+'</td><td>'+x(u.location)+'</td><td>'+stage(u.status)+'</td><td>'+D.leads.filter(l=>l.owner===u.id).length+'</td><td>'+u.lastLogin+'</td><td>'+ (u.id!==user().id?button(u.status==='Active'?'Deactivate':'Activate','user-'+u.id,'tl-link'):'—')+'</td></tr>').join('')+'</tbody></table></div></article>'}
function team(){let p=document.querySelector('#page');p.innerHTML=title('Team Performance','Objective activity and outcome metrics by active owner.')+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>Owner</th><th>Total leads</th><th>Active</th><th>Converted</th><th>Lost</th><th>Nurture</th><th>Due today</th><th>Missed</th><th>Meetings</th><th>Conversion</th><th>Avg. aging</th></tr></thead><tbody>'+D.users.filter(u=>u.status==='Active').map(u=>{let ls=D.leads.filter(l=>l.owner===u.id);return '<tr><td><b>'+x(u.name)+'</b><small>'+x(u.department)+'</small></td><td>'+ls.length+'</td><td>'+ls.filter(l=>l.status==='Open').length+'</td><td>'+ls.filter(l=>l.stage==='Active Client').length+'</td><td>'+ls.filter(l=>l.stage==='Lost').length+'</td><td>'+ls.filter(l=>l.stage==='Nurture').length+'</td><td>'+ls.filter(l=>l.follow===DAY).length+'</td><td>'+ls.filter(l=>sooner(l.follow)&&l.status==='Open').length+'</td><td>'+D.meetings.filter(m=>lead(m.lead).owner===u.id).length+'</td><td>'+(ls.length?Math.round(ls.filter(l=>l.stage==='Active Client').length/ls.length*100):0)+'%</td><td>'+(ls.length?Math.round(ls.reduce((a,l)=>a+l.age,0)/ls.length):0)+'d</td></tr>'}).join('')+'</tbody></table></div></article>'}
function settings(){document.querySelector('#page').innerHTML=title('Settings','System-level workflow lists and future integration settings.')+'<div class="module-list"><button class="module-tile" data-action="info-stages"><i>◫</i><b>Stages & statuses</b><small>Manage lifecycle values used in pipeline views.</small></button><button class="module-tile" data-action="info-sources"><i>◌</i><b>Lead sources</b><small>Control source taxonomy and reporting categories.</small></button><button class="module-tile" data-action="info-notifications"><i>♧</i><b>Notifications</b><small>In-app states with email-ready architecture.</small></button><button class="module-tile" data-action="reset"><i>↻</i><b>Reset demo data</b><small>Restore original fictional CRM data.</small></button></div>'}
function auditPage(){let p=document.querySelector('#page');p.innerHTML=title('Audit Log','Major CRM actions stay visible for Super Admin review.')+'<article class="tl-card no-pad"><div class="table-wrap"><table class="tl-table"><thead><tr><th>User</th><th>Action</th><th>Record</th><th>Timestamp</th><th>Previous value</th><th>New value</th></tr></thead><tbody>'+D.audit.map(a=>'<tr><td>'+x(a.user)+'</td><td><b>'+x(a.action)+'</b></td><td>'+x(a.record)+'</td><td>'+x(a.time)+'</td><td>'+x(a.previous)+'</td><td>'+x(a.next)+'</td></tr>').join('')+'</tbody></table></div></article>'}
function search(){let p=document.querySelector('#page'),q=U.query.toLowerCase(),ls=mine().filter(l=>[l.id,co(l.company).name,ct(l.contact).name,ct(l.contact).email,ct(l.contact).phone,ow(l.owner).name].join(' ').toLowerCase().includes(q)),cs=(admin()?D.companies:D.companies.filter(c=>mine().some(l=>l.company===c.id))).filter(c=>[c.name,c.website,c.industry].join(' ').toLowerCase().includes(q)),ts=(admin()?D.contacts:D.contacts.filter(c=>mine().some(l=>l.company===c.company))).filter(c=>[c.name,c.email,c.phone].join(' ').toLowerCase().includes(q));p.innerHTML=title('Global Search','Search companies, contacts, leads, phone numbers, emails, websites and owners.')+'<div class="tl-filters"><input class="filter-input" id="searchInput" value="'+x(U.query)+'" placeholder="Start typing to search all records…" style="min-width:350px"></div><section class="tl-grid"><article class="tl-card"><div class="tl-card-head"><h2>COMPANIES · '+cs.length+'</h2></div>'+cs.map(c=>'<div class="urgent-item"><div class="urgent-copy"><b>'+x(c.name)+'</b><small>'+x(c.industry)+' · '+x(c.website)+'</small></div>'+stage(c.status)+'</div>').join('')+(cs.length?'':empty('No companies match','Try another search.'))+'<div class="tl-card-head" style="margin-top:21px"><h2>CONTACTS · '+ts.length+'</h2></div>'+ts.map(c=>'<div class="urgent-item"><div class="urgent-copy"><b>'+x(c.name)+'</b><small>'+x(co(c.company).name)+' · '+x(c.email)+' · '+x(c.phone)+'</small></div></div>').join('')+'</article><article class="tl-card"><div class="tl-card-head"><h2>LEADS · '+ls.length+'</h2></div>'+ls.map(l=>'<button class="urgent-item" data-lead="'+l.id+'" style="background:none;border-left:0;border-right:0;width:100%;text-align:left"><div class="urgent-copy"><b>'+x(co(l.company).name)+' · '+l.id+'</b><small>'+x(ct(l.contact).name)+' · '+x(ow(l.owner).name)+' · '+x(l.next)+'</small></div>'+stage(l.stage)+'</button>').join('')+(ls.length?'':empty('No leads match','Try another search.'))+'</article></section>'}
function detail(id){let l=lead(id);if(!l||!can(l)){deny();return}U.lead=id;let c=co(l.company),t=ct(l.contact),as=D.activities.filter(a=>a.lead===l.id),tabs=['Overview','Contacts','Activity Timeline','Meetings','Follow-ups','Brief','Pitch','Commercials','Contract / PO','Onboarding','Nurture','Documents'];document.querySelector('#page').innerHTML='<article class="detail-header"><div class="detail-meta">'+stage(l.stage)+' '+pri(l.priority)+' '+stage(l.status)+'<span style="font-size:11px;color:var(--muted)">Owner: <b>'+x(ow(l.owner).name)+'</b></span></div><h1>'+x(c.name)+'</h1><p>'+x(c.industry)+' · '+x(c.city)+' · '+x(t.name)+', '+x(t.designation)+'</p><div class="detail-actions">'+button('Call','quick-call')+button('Email','quick-email')+button('WhatsApp','quick-whatsapp')+button('Schedule Meeting','detail-meeting')+button('Add Activity','detail-activity')+(admin()?button('Change Owner','detail-owner'):'')+button('Change stage','detail-stage','tl-primary')+button('Mark lost','detail-lost','tl-danger')+'</div></article><div class="tl-tabs">'+tabs.map(z=>'<button class="tl-tab '+(U.tab===z?'active':'')+'" data-tab="'+z+'">'+z+'</button>').join('')+'</div><section id="detail"></section>';let e=document.querySelector('#detail');if(U.tab==='Overview')e.innerHTML='<div class="detail-grid"><article class="tl-card"><div class="tl-card-head"><h2>OPPORTUNITY</h2>'+button('Edit details','edit-lead','tl-link')+'</div><div class="info-grid">'+[['Lead ID',l.id],['Potential requirement',l.service],['Opportunity value','₹'+l.value.toLocaleString('en-IN')],['Lead source',l.source],['Current stage',l.stage],['Next action',l.next],['Follow-up',date(l.follow)+' '+l.time],['Route',l.known?'Known / existing: commercials first':'New / unknown: pitch first'],['Stage age',l.age+' days']].map(a=>'<div class="info-field"><small>'+a[0]+'</small><b>'+x(a[1])+'</b></div>').join('')+'</div><div class="tl-card-head" style="margin:22px 0 10px"><h2>ROUTE DECISION</h2></div><div class="workflow">'+workflow(l)+'</div></article><aside class="tl-card"><div class="tl-card-head"><h2>RECENT ACTIVITY</h2></div><div class="timeline">'+as.map(activity).join('')+(as.length?'':empty('No activity recorded','Use Add Activity to start the history.'))+'</div></aside></div>';else if(U.tab==='Contacts')e.innerHTML=contactList(l);else if(U.tab==='Activity Timeline')e.innerHTML='<article class="tl-card"><div class="tl-card-head"><h2>ACTIVITY HISTORY</h2>'+button('+ Add activity','detail-activity','tl-primary')+'</div><div class="timeline">'+as.map(activity).join('')+'</div></article>';else if(U.tab==='Meetings')e.innerHTML=recordTable(D.meetings.filter(m=>m.lead===l.id),['title','date','time','type','status'],'meeting');else if(U.tab==='Follow-ups')e.innerHTML=followDetail(l);else e.innerHTML=lifecycle(l,U.tab)}
function workflow(l){let r=l.known?['Brief','Commercials','Contract / PO','Onboarding','Active Client','Pitch']:['Brief','Pitch','Commercials','Contract / PO','Onboarding','Active Client'],i=r.indexOf(l.stage);return r.map((s,n)=>'<div class="workflow-step '+(n<i?'done':n===i?'current':'')+'"><i>'+ (n+1)+'</i><b>'+s+'</b></div>').join('')}
function activity(a){return '<div class="timeline-item"><b>'+x(a.type)+' · '+x(a.outcome)+'</b><small>'+date(a.date)+' · '+x(ow(a.owner).name)+'</small><small>'+x(a.notes)+'</small></div>'}
function contactList(l){let cs=D.contacts.filter(c=>c.company===l.company);return '<article class="tl-card"><div class="tl-card-head"><h2>CONTACTS · '+cs.length+'</h2>'+button('+ Add contact','detail-contact','tl-primary')+'</div><div class="table-wrap"><table class="tl-table"><thead><tr><th>Contact ID</th><th>Name</th><th>Designation</th><th>Phone</th><th>Email</th><th>Decision maker</th></tr></thead><tbody>'+cs.map(c=>'<tr><td>'+c.id+'</td><td><b>'+x(c.name)+'</b></td><td>'+x(c.designation)+'</td><td>'+x(c.phone)+'</td><td>'+x(c.email)+'</td><td>'+ (c.decision?'Yes':'No')+'</td></tr>').join('')+'</tbody></table></div></article>'}
function followDetail(l){let fs=D.followups.filter(f=>f.lead===l.id);return '<article class="tl-card"><div class="tl-card-head"><h2>FOLLOW-UPS</h2>'+button('+ Schedule','detail-followup','tl-primary')+'</div>'+fs.map(f=>'<div class="urgent-item"><div class="urgent-copy"><b>'+x(f.action)+'</b><small>'+date(f.date)+' · '+f.time+' · '+f.status+'</small></div>'+pri(f.priority)+button('Complete','complete-'+f.id,'tl-link')+'</div>').join('')+'</article>'}
function lifecycle(l,tab){let content={Brief:'Capture a structured brief before the opportunity moves forward.',Pitch:'Versioned pitch records track team assignment, reviews and client feedback.',Commercials:'Commercial versions protect negotiation history instead of overwriting it.','Contract / PO':'Track final scope, price, payment terms and documents.',Onboarding:'Mandatory checklist gates protect the move to Active Client.',Nurture:'Lost, later and no-response contacts stay in the database and can reconnect.',Documents:'Document storage is ready for a future secure file service.'}[tab];return '<article class="tl-card"><div class="tl-card-head"><h2>'+tab.toUpperCase()+'</h2>'+button(tab==='Nurture'&&['Lost','Nurture'].includes(l.stage)?'Reconnect':'Add record','life-'+tab,'tl-primary')+'</div><p class="muted">'+content+'</p>'+ (tab==='Brief'?'<div class="info-grid"><div class="info-field"><small>Status</small><b>Awaiting clarification</b></div><div class="info-field"><small>Known client / industry</small><b>'+ (l.known?'Known / Existing':'New / Unknown')+'</b></div></div>':'')+'</article>'}
function modal(title,body,confirm,action){M.innerHTML='<div class="modal-backdrop"><section class="tl-modal"><header class="modal-head"><div><h2>'+title+'</h2><p>Changes are saved to this browser’s local MVP data store.</p></div>'+button('×','modal-close','icon-control')+'</header><div class="modal-body">'+body+'</div><footer class="modal-foot">'+button('Cancel','modal-close')+button(confirm,action||'modal-save','tl-primary')+'</footer></section></div>'}
const input=(label,name,value,type)=>'<label>'+label+'<input name="'+name+'" type="'+(type||'text')+'" value="'+x(value)+'"></label>';
const select=(label,name,opts,value)=>'<label>'+label+'<select name="'+name+'">'+opts.map(o=>'<option '+(o===value?'selected':'')+'>'+x(o)+'</option>').join('')+'</select></label>';
const area=(label,name,value)=>'<label class="full">'+label+'<textarea name="'+name+'" rows="3">'+x(value)+'</textarea></label>';
function leadForm(edit){let l=edit||{},c=edit?co(l.company):{},t=edit?ct(l.contact):{},s=U.formStep;let body='<div class="stepper">'+['Company','Contact','Opportunity','Ownership','Next action'].map((z,i)=>'<button class="'+(i+1===s?'active':'')+'">'+(i+1)+'. '+z+'</button>').join('')+'</div>';if(s===1)body+='<div class="form-section"><h3>Company information</h3><div class="form-grid2">'+input('Company name *','company',c.name)+select('Industry *','industry',['Real Estate','Healthcare','Agriculture','Retail','Education','Automobile','FMCG','BFSI','IT / SaaS','Hospitality','Pharma','Manufacturing','D2C / E-commerce','Other'],c.industry)+input('City','city',c.city)+input('Website','website',c.website)+input('Existing agency','agency',c.agency)+area('Marketing activity','marketing',c.marketing||'')+'</div></div>';if(s===2)body+='<div class="form-section"><h3>Primary contact</h3><div class="form-grid2">'+input('Contact name *','contact',t.name)+input('Designation','designation',t.designation)+input('Phone','phone',t.phone,'tel')+input('Email','email',t.email,'email')+select('Decision maker','decision',['Yes','No'],t.decision?'Yes':'No')+'</div></div>';if(s===3)body+='<div class="form-section"><h3>Opportunity</h3><div class="form-grid2">'+input('Potential requirement *','service',l.service)+select('Lead source *','source',['LinkedIn','Google','Competitor research','Referral','Employee referral','Industry event','Tender/RFP','Funding news','Newspaper','Magazine','Digital/social','Trade publication','Other'],l.source)+input('Opportunity value','value',l.value||'','number')+select('Priority','priority',['High','Medium','Low'],l.priority||'Medium')+area('Opportunity description','description',l.service||'')+'</div></div>';if(s===4)body+='<div class="form-section"><h3>Ownership</h3><div class="form-grid2">'+select('Owner *','owner',D.users.filter(u=>u.status==='Active').map(u=>u.name),edit?ow(l.owner).name:user().name)+'</div></div>';if(s===5)body+='<div class="form-section"><h3>Next action</h3><div class="form-grid2">'+input('Next action *','next',l.next)+input('Follow-up date *','follow',l.follow||DAY,'date')+input('Follow-up time','time',l.time||'10:00','time')+select('Known client / industry?','known',['No / Unknown','Yes / Existing'],l.known?'Yes / Existing':'No / Unknown')+'</div></div>';modal(edit?'Edit lead':'Add lead',body,s===5?(edit?'Save lead':'Create lead'):'Continue','lead-step');}
function ownerByName(n){return D.users.find(u=>u.name===n)||user()}
function formData(){return Object.fromEntries(new FormData(M.querySelector('form')||M.querySelector('.modal-body')).entries())}
function addLeadValues(f,edit){if(!f.company||!f.contact||!f.next||!f.follow)return false;let company=D.companies.find(c=>c.name.toLowerCase()===f.company.toLowerCase()),cid;if(company)cid=company.id;else{cid=gid('CMP');D.companies.push({id:cid,name:f.company,industry:f.industry,city:f.city,website:f.website,agency:f.agency,source:f.source,status:'Active'})}let contact=edit?ct(edit.contact):null;if(contact)Object.assign(contact,{name:f.contact,designation:f.designation,phone:f.phone,email:f.email,decision:f.decision==='Yes'});else{contact={id:gid('CON'),company:cid,name:f.contact,designation:f.designation,phone:f.phone,email:f.email,decision:f.decision==='Yes'};D.contacts.push(contact)}let owner=ownerByName(f.owner);if(edit){let old=edit.owner;Object.assign(edit,{company:cid,contact:contact.id,owner:owner.id,service:f.service,source:f.source,value:Number(f.value||0),priority:f.priority,next:f.next,follow:f.follow,time:f.time,known:f.known==='Yes / Existing'});if(old!==owner.id)audit('Owner changed',edit,ow(old).name,owner.name);act(edit,'Lead edited','Lead details updated',f.description);audit('Lead edited',edit,'Lead details','Updated');}else{let l={id:gid('LED'),company:cid,contact:contact.id,owner:owner.id,stage:'New',status:'Open',priority:f.priority,source:f.source,value:Number(f.value||0),next:f.next,follow:f.follow,time:f.time,last:DAY,known:f.known==='Yes / Existing',age:0,service:f.service};D.leads.unshift(l);D.followups.unshift({id:gid('FUP'),lead:l.id,date:l.follow,time:l.time,action:l.next,priority:l.priority,status:l.follow===DAY?'Due today':'Upcoming'});act(l,'Lead created','New lead created','Company and primary contact captured.');audit('Lead created',l,'—','New lead');U.lead=l.id}save();return true}
function quickActivity(type){let l=lead(U.lead);modal('Add '+type,'<div class="form-section"><div class="form-grid2">'+input('Outcome *','outcome','')+area('Notes','notes','')+input('Next action','next',l.next)+input('Next follow-up','follow',l.follow,'date')+'</div></div>','Save activity','save-activity')}
function meetingForm(){let ls=mine();modal('Schedule meeting','<div class="form-section"><div class="form-grid2">'+select('Related lead *','lead',ls.map(l=>co(l.company).name+' · '+l.id),U.lead?co(lead(U.lead).company).name+' · '+U.lead:'')+input('Meeting title *','title','')+input('Date *','date',DAY,'date')+input('Time *','time','11:00','time')+select('Meeting type','type',['Video call','In person','Phone'])+area('Agenda','agenda','')+'</div></div>','Schedule meeting','save-meeting')}
function followForm(reconnect){let ls=mine();modal(reconnect?'Schedule reconnect':'Schedule follow-up','<div class="form-section"><div class="form-grid2">'+select('Related lead *','lead',ls.map(l=>co(l.company).name+' · '+l.id),U.lead?co(lead(U.lead).company).name+' · '+U.lead:'')+input('Action *','action',reconnect?'Reconnect':'')+input('Date *','date',reconnect?'2026-10-17':'2026-09-18','date')+input('Time','time','10:00','time')+select('Priority','priority',['High','Medium','Low'],'Medium')+'</div></div>','Schedule','save-followup')}
function completeFollow(id){let f=D.followups.find(z=>z.id===id),l=lead(f.lead);modal('Complete follow-up','<p><b>'+x(f.action)+'</b></p><div class="form-section"><div class="form-grid2">'+input('Outcome *','outcome','')+area('Notes *','notes','')+input('Next action *','next','')+input('Next follow-up date *','follow','2026-09-19','date')+input('Next follow-up time','time','10:00','time')+'</div></div>','Mark complete','complete-followup');M.dataset.follow=id}
function stageForm(l){modal('Change stage','<p>Every change creates a history and audit entry.</p><div class="form-section"><div class="form-grid2">'+select('New stage','stage',STAGES.concat(['Nurture','Lost']),l.stage)+area('Reason / comment *','reason','')+'</div></div>','Change stage','save-stage')}
function lostForm(l){modal('Mark as lost / not interested','<p>This preserves the record and allows the prospect to enter Nurture. Close details are mandatory.</p><div class="form-section"><div class="form-grid2">'+select('Reason *','reason',['Budget','Timing','No requirement','Creative / pitch','Competitor','Existing agency','Internal decision','No response','Other'],'Budget')+area('Close comment *','comment','')+select('Move to nurture?','nurture',['Yes','No'],'Yes')+'</div></div>','Close lead','save-lost')}
function ownerForm(l){modal('Change owner','<p>Reassignment is added to the audit history.</p><div class="form-section"><div class="form-grid2">'+select('New owner','owner',D.users.filter(u=>u.status==='Active').map(u=>u.name),ow(l.owner).name)+area('Reason','reason','')+'</div></div>','Reassign','save-owner')}
function contactForm(){modal('Add contact','<div class="form-section"><div class="form-grid2">'+select('Company *','company',(admin()?D.companies:D.companies.filter(c=>mine().some(l=>l.company===c.id))).map(c=>c.name),U.lead?co(lead(U.lead).company).name:'')+input('Name *','name','')+input('Designation','designation','')+input('Phone','phone','','tel')+input('Email','email','','email')+select('Decision maker','decision',['No','Yes'],'No')+'</div></div>','Create contact','save-contact')}
function companyForm(){modal('Add company','<div class="form-section"><div class="form-grid2">'+input('Company name *','name','')+select('Industry *','industry',['Real Estate','Healthcare','Agriculture','Retail','Education','Automobile','FMCG','BFSI','IT / SaaS','Hospitality','Pharma','Manufacturing','D2C / E-commerce','Other'],'Other')+input('City','city','')+input('Website','website','')+input('Existing agency','agency','')+'</div></div>','Create company','save-company')}
function userForm(){modal('Add user / owner','<div class="form-section"><div class="form-grid2">'+input('Name *','name','')+input('Email *','email','','email')+select('Role','role',['USER / OWNER','SUPER ADMIN'],'USER / OWNER')+input('Department','department','')+input('Location','location','')+'</div></div>','Create user','save-user')}
function selectPicks(){return Array.from(document.querySelectorAll('.pick:checked')).map(i=>i.value)}
function bulk(k){let ids=selectPicks();if(!ids.length){flash('Select one or more leads first.');return}if(k==='owner')modal('Assign owner','<p>Assign '+ids.length+' selected lead(s). The change will be recorded.</p><div class="form-section"><div class="form-grid2">'+select('Owner','owner',D.users.filter(u=>u.status==='Active').map(u=>u.name),'')+'</div></div>','Assign','bulk-owner-save');else modal('Change stage','<p>Stage changes are never silent.</p><div class="form-section"><div class="form-grid2">'+select('New stage','stage',STAGES,'New')+area('Reason *','reason','')+'</div></div>','Change stage','bulk-stage-save')}
function notifications(){let n=document.querySelector('#notes');if(n.innerHTML){n.innerHTML='';return}n.innerHTML='<section class="notification-panel"><div class="tl-card-head"><h3>Notifications</h3>'+button('Mark all read','mark-read','tl-link')+'</div>'+D.notifications.map(q=>'<div class="notif"><b>'+x(q.text)+'</b><small>'+q.type+(q.unread?' · Unread':'')+'</small></div>').join('')+'</section>'}
function exportRows(name,rows){if(!rows.length){flash('Nothing to export.');return}let keys=Array.from(new Set(rows.flatMap(o=>Object.keys(o)))),csv=[keys.join(',')].concat(rows.map(o=>keys.map(k=>'"'+String(o[k]||'').replaceAll('"','""')+'"').join(','))).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();flash('CSV export prepared.')}
R.onclick=e=>{let a=e.target.closest('[data-action],[data-go],[data-lead],[data-tab]');if(!a)return;e.preventDefault();if(a.dataset.go)return go(a.dataset.go);if(a.dataset.lead){U.tab='Overview';return detail(a.dataset.lead)}if(a.dataset.tab){U.tab=a.dataset.tab;return detail(U.lead)}let q=a.dataset.action;if(q==='show-pass'){let i=document.querySelector('#password');i.type=i.type==='password'?'text':'password';a.textContent=i.type==='password'?'Show':'Hide'}else if(q==='forgot')login(true,0);else if(q==='back-login')login();else if(q==='verify-reset')login(true,2);else if(q==='demo-admin')auth('USR-001');else if(q==='demo-owner')auth('USR-003');else if(q==='return-dashboard')go('dashboard');else if(q==='menu')document.querySelector('#side').classList.toggle('open');else if(q==='notifications')notifications();else if(q==='mark-read'){D.notifications.forEach(n=>n.unread=false);save();render()}else if(q==='profile')modal('Profile','<p><b>'+x(user().name)+'</b><br>'+x(user().role)+' · '+x(user().location)+'</p><p class="muted">This demo uses a simulated auth adapter. Real authentication belongs in a protected backend.</p>','Log out','logout');else if(q==='modal-close')M.innerHTML='';else if(q==='add-lead'){U.formStep=1;U.draft={};leadForm()}else if(q==='edit-lead'){U.formStep=1;leadForm(lead(U.lead))}else if(q==='toggle-kanban'){U.kanban=!U.kanban;leads()}else if(q==='open-leads')go('leads');else if(q==='open-followups')go('followups');else if(q==='open-team')go('team');else if(q==='add-company')companyForm();else if(q==='add-contact'||q==='detail-contact')contactForm();else if(q==='add-activity'||q==='detail-activity')quickActivity('Activity');else if(q==='add-meeting'||q==='detail-meeting')meetingForm();else if(q==='add-followup'||q==='detail-followup')followForm();else if(q==='add-reconnect')followForm(true);else if(q==='detail-stage')stageForm(lead(U.lead));else if(q==='detail-lost')lostForm(lead(U.lead));else if(q==='detail-owner')ownerForm(lead(U.lead));else if(q==='quick-call'||q==='quick-email'||q==='quick-whatsapp')flash(q.replace('quick-','').toUpperCase()+' action prepared for '+ct(lead(U.lead).contact).name+'.');else if(q==='bulk-owner')bulk('owner');else if(q==='bulk-stage')bulk('stage');else if(q==='add-user')userForm();else if(q==='reset')modal('Reset demo data','<p>This removes local demo changes from this device and restores fictional sample data.</p>','Reset data','confirm-reset');else if(q.startsWith('complete-')){let id=q.replace('complete-','');if(id.startsWith('meeting-'))completeMeeting(id.replace('meeting-',''));else completeFollow(id)}else if(q.startsWith('user-'))toggleUser(q.replace('user-',''));else if(q.startsWith('export-'))exportRows('tempest-'+q.replace('export-','')+'.csv',mine());else if(q.startsWith('life-'))lifeAction(q.replace('life-',''));else if(q.startsWith('info-'))modal(q.replace('info-',''),' <p>Configuration is ready for a connected backend administrator workflow.</p>','Done','modal-close');};
R.oninput=e=>{if(e.target.id==='leadQuery'){U.query=e.target.value;leads()}if(e.target.id==='global'||e.target.id==='searchInput'){U.query=e.target.value}};
R.onchange=e=>{if(e.target.id==='leadStage'){U.filter=e.target.value;leads()}if(e.target.id==='all')document.querySelectorAll('.pick').forEach(i=>i.checked=e.target.checked)};
R.onkeydown=e=>{if(e.target.id==='global'&&e.key==='Enter'){go('search')}};
R.onsubmit=e=>{e.preventDefault();let f=Object.fromEntries(new FormData(e.target).entries());if(e.target.dataset.form==='login'){let u=D.users.find(u=>u.email===f.email&&u.status==='Active');if(!u){flash('Invalid credentials or inactive account. Use a demo workspace button.');return}auth(u.id)}if(e.target.dataset.form==='forgot'){if(!D.users.some(u=>u.email===f.email)){flash('We could not find an active account with that email.');return}login(true,1)}if(e.target.dataset.form==='reset'){if(f.password!==f.confirm){flash('The passwords do not match.');return}login(true,3)}};
M.onclick=e=>{let a=e.target.closest('[data-action]');if(!a)return;let q=a.dataset.action;if(q==='modal-close'){M.innerHTML='';return}if(q==='logout'){session=null;sessionStorage.removeItem(S);M.innerHTML='';login();return}if(q==='confirm-reset'){localStorage.removeItem(K);D=seed();save();M.innerHTML='';flash('Demo data reset.');render();return}let f=Object.fromEntries(new FormData(M.querySelector('.modal-body')).entries());if(q==='lead-step'){Object.assign(U.draft,f);if(U.formStep<5){U.formStep++;leadForm();}else{if(!addLeadValues(U.draft,U.lead?lead(U.lead):null)){flash('Company, contact, next action and date are required.');return}M.innerHTML='';flash(U.lead?'Lead updated.':'Lead created with first follow-up.');let id=U.lead;U.draft={};U.formStep=1;if(id)detail(id);else render();}}else if(q==='save-activity'){let l=lead(U.lead);if(!f.outcome){flash('Outcome is required.');return}act(l,'Activity',f.outcome,f.notes);if(f.next){l.next=f.next;l.follow=f.follow;D.followups.unshift({id:gid('FUP'),lead:l.id,date:f.follow,time:'10:00',action:f.next,priority:l.priority,status:f.follow===DAY?'Due today':'Upcoming'})}audit('Activity added',l,'—','Activity');M.innerHTML='';flash('Activity recorded.');detail(l.id)}else if(q==='save-meeting'){let id=f.lead.split(' · ').pop(),l=lead(id);if(!l||!f.title){flash('Lead and meeting title are required.');return}D.meetings.unshift({id:gid('MET'),lead:id,title:f.title,date:f.date,time:f.time,type:f.type,status:'Scheduled',notes:f.agenda});act(l,'Meeting','Meeting scheduled',f.title);audit('Meeting created',l,'—',f.title);save();M.innerHTML='';flash('Meeting scheduled and activity logged.');render()}else if(q==='save-followup'){let id=f.lead.split(' · ').pop(),l=lead(id);if(!l||!f.action||!f.date){flash('Lead, action and date are required.');return}l.next=f.action;l.follow=f.date;l.time=f.time;D.followups.unshift({id:gid('FUP'),lead:id,date:f.date,time:f.time,action:f.action,priority:f.priority,status:f.date===DAY?'Due today':'Upcoming'});act(l,'Follow-up','Follow-up scheduled',f.action);save();M.innerHTML='';flash('Follow-up scheduled.');render()}else if(q==='complete-followup'){let id=M.dataset.follow,fo=D.followups.find(z=>z.id===id),l=lead(fo.lead);if(!f.outcome||!f.notes||!f.next||!f.follow){flash('Outcome, notes, next action and date are required.');return}fo.status='Completed';l.next=f.next;l.follow=f.follow;l.time=f.time;act(l,'Follow-up',f.outcome,f.notes);D.followups.unshift({id:gid('FUP'),lead:l.id,date:f.follow,time:f.time,action:f.next,priority:l.priority,status:f.follow===DAY?'Due today':'Upcoming'});audit('Follow-up completed',l,fo.action,f.next);save();M.innerHTML='';flash('Follow-up completed and next action scheduled.');render()}else if(q==='save-stage'){let l=lead(U.lead);if(!f.reason){flash('A reason or comment is required.');return}if(f.stage==='Lost'){M.innerHTML='';lostForm(l);return}let old=l.stage;l.stage=f.stage;l.age=0;if(f.stage==='Nurture')l.status='Later';act(l,'Stage change','Moved from '+old+' to '+f.stage,f.reason);audit('Stage changed',l,old,f.stage);M.innerHTML='';flash('Stage history updated.');detail(l.id)}else if(q==='save-lost'){let l=lead(U.lead);if(!f.reason||!f.comment){flash('Reason and close comment are required.');return}let old=l.stage;l.stage=f.nurture==='Yes'?'Nurture':'Lost';l.status='Not interested';l.reason=f.reason;l.next='Reconnect when relevant';l.follow='2026-11-17';act(l,'Stage change','Lead closed as lost',f.reason+': '+f.comment);audit('Lead marked lost',l,old,l.stage);M.innerHTML='';flash('History preserved. Lead '+(l.stage==='Nurture'?'moved to nurture.':'closed.'));detail(l.id)}else if(q==='save-owner'||q==='bulk-owner-save'){let targets=q==='save-owner'?[lead(U.lead)]:selectPicks().map(lead),owner=ownerByName(f.owner);targets.forEach(l=>{let old=l.owner;l.owner=owner.id;act(l,'Owner changed','Assigned to '+owner.name,f.reason||'Reassigned');audit('Owner changed',l,ow(old).name,owner.name)});M.innerHTML='';flash('Owner assignment updated.');render()}else if(q==='bulk-stage-save'){if(!f.reason){flash('A reason is required.');return}selectPicks().map(lead).forEach(l=>{let old=l.stage;l.stage=f.stage;l.age=0;act(l,'Stage change','Moved from '+old+' to '+f.stage,f.reason);audit('Stage changed',l,old,f.stage)});M.innerHTML='';flash('Stage history updated.');render()}else if(q==='save-contact'){if(!f.name){flash('Contact name is required.');return}let c=D.companies.find(z=>z.name===f.company);D.contacts.push({id:gid('CON'),company:c.id,name:f.name,designation:f.designation,phone:f.phone,email:f.email,decision:f.decision==='Yes'});save();M.innerHTML='';flash('Contact created.');U.lead?detail(U.lead):render()}else if(q==='save-company'){if(!f.name){flash('Company name is required.');return}if(D.companies.some(c=>c.name.toLowerCase()===f.name.toLowerCase())){flash('Possible existing company found.');return}D.companies.push({id:gid('CMP'),name:f.name,industry:f.industry,city:f.city,website:f.website,agency:f.agency,source:'Other',status:'Prospect'});save();M.innerHTML='';flash('Company created.');render()}else if(q==='save-user'){if(!f.name||!f.email){flash('Name and email are required.');return}D.users.push({id:gid('USR'),name:f.name,email:f.email,role:f.role,department:f.department,location:f.location,status:'Active',lastLogin:'Never'});save();M.innerHTML='';flash('User created.');render()}};
function completeMeeting(id){let m=D.meetings.find(z=>z.id===id);if(!m||m.status==='Completed'){flash('Open the lead record to view this completed meeting.');return}modal('Complete meeting','<div class="form-section"><div class="form-grid2">'+area('Meeting notes *','notes','')+input('Outcome *','outcome','')+input('Next action *','next','')+input('Follow-up date *','follow','2026-09-18','date')+'</div></div>','Complete meeting','finish-meeting');M.dataset.meeting=id}
function toggleUser(id){let u=D.users.find(z=>z.id===id);if(u.status==='Inactive'){u.status='Active';save();flash('User activated.');render();return}let n=D.leads.filter(l=>l.owner===id).length;modal('Deactivate '+x(u.name)+'?','<p>Deactivating this user will move '+n+' assigned lead(s) to Super Admin unless you reassign them first.</p>','Deactivate','deactivate-user');M.dataset.user=id}
function lifeAction(tab){let l=lead(U.lead);if(tab==='Nurture'&&['Lost','Nurture'].includes(l.stage)){let old=l.stage;l.stage='Connected';l.status='Open';l.next='Schedule reconnect meeting';l.follow='2026-09-18';act(l,'Reconnect','Lead reconnected','Moved from nurture to active opportunity.');audit('Nurture reconnected',l,old,'Connected');save();flash('Lead reconnected. Schedule a meeting next.');detail(l.id)}else flash('Open workflow record creation is ready for backend integration in this MVP.')}
M.addEventListener('click',e=>{let q=e.target.closest('[data-action]');if(!q)return;if(q.dataset.action==='finish-meeting'){let f=Object.fromEntries(new FormData(M.querySelector('.modal-body')).entries()),m=D.meetings.find(z=>z.id===M.dataset.meeting),l=lead(m.lead);if(!f.notes||!f.outcome||!f.next||!f.follow){flash('Notes, outcome, next action and follow-up are required.');return}m.status='Completed';m.notes=f.notes;l.next=f.next;l.follow=f.follow;act(l,'Meeting',f.outcome,f.notes);D.followups.unshift({id:gid('FUP'),lead:l.id,date:f.follow,time:'10:00',action:f.next,priority:l.priority,status:'Upcoming'});audit('Meeting completed',l,'Scheduled','Completed');save();M.innerHTML='';flash('Meeting completed with notes and next action.');render()}if(q.dataset.action==='deactivate-user'){let u=D.users.find(z=>z.id===M.dataset.user),a=D.users.find(z=>z.role==='SUPER ADMIN'&&z.status==='Active');D.leads.filter(l=>l.owner===u.id).forEach(l=>{l.owner=a.id;audit('Owner changed',l,u.name,a.name)});u.status='Inactive';save();M.innerHTML='';flash('User deactivated and leads reassigned to Super Admin.');render()}});
window.addEventListener('hashchange',()=>{if(session){U.route=location.hash.slice(1)||'dashboard';render()}});
/* Modal bodies are lightweight form containers; normalize them to FormData. */
const NativeFormData=window.FormData;
window.FormData=function(source){if(source instanceof HTMLFormElement)return new NativeFormData(source);const fd=new NativeFormData();if(source&&source.querySelectorAll)source.querySelectorAll('input,select,textarea').forEach(e=>{if(e.name)fd.append(e.name,e.value)});return fd};
R.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(a&&a.dataset.action==='add-lead')U.lead=null},true);
render();
